const filteredMatches = useMemo(() => {
  // Сначала убираем вообще все пустые элементы из массива
  let result = matches.filter((m) => m && m.homeTeam && m.awayTeam);

  if (searchQuery) {
    result = result.filter(
      (m) =>
        m.homeTeam.name.toLowerCase().includes(searchQuery) ||
        m.awayTeam.name.toLowerCase().includes(searchQuery) ||
        (m.homeTeam.name_ru &&
          m.homeTeam.name_ru.toLowerCase().includes(searchQuery)),
    );
  }

  if (selectedLeague) {
    result = result.filter((m) => m.league === selectedLeague);
  }

  if (selectedDate) {
    result = result.filter((m) => {
      if (!m.utcDate) return false;
      return m.utcDate.substring(0, 10) === selectedDate;
    });
  }

  return result;
}, [matches, selectedLeague, selectedDate, searchQuery]);
